                return s;
            };

            // [76] BB\script\output\_sce04_c303_0040_eng#4
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#4"] = (s) => {
                R(ref s, "I've never taken the life of another.\r\nNor have I instructed another to kill.", "Je n'ai jamais ôté la vie d'autrui.\r\nNi ordonné à quiconque de tuer.");
                return s;
            };

            // [77] BB\script\output\_sce04_c303_0040_eng#5
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#5"] = (s) => {
                R(ref s, "I've been investigating the truth behind the Reaper for\r\nyears. And I was aware of Gregson's involvement.", "J'enquête sur la vérité du Faucheur depuis des années.\r\nEt j'avais connaissance du rôle de Gregson.");
                return s;
            };

            // [78] BB\script\output\_sce04_c303_0040_eng#6
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#6"] = (s) => {
                R(ref s, "That's the reason why I went to Fresno Street that day,\r\nand how I came to discover the body.", "Voilà pourquoi je me suis rendu à Fresno Street ce jour-là,\r\net comment j'ai découvert le corps.");
                return s;
            };

            // [79] BB\script\output\_sce04_c303_0040_eng#7
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#7"] = (s) => {
                R(ref s, "The point is, no common thread exists between myself,\r\nGregson and Dr Wilson.", "En substance, aucun lien n'existe entre moi,\r\nGregson et le Dr Wilson.");
                return s;
            };

            // [80] BB\script\output\_sce04_c303_0040_eng#8
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#8"] = (s) => {
                R(ref s, "Clearly, therefore, there's no reason to suspect me of\r\nbeing behind the assassin exchange.", "Il est donc évident qu'aucune raison ne justifie de me\r\nsoupçonner d'être derrière cet échange d'assassins.");
                return s;
            };

            // [81] BB\script\output\_sce04_c303_0040_eng#9
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#9"] = (s) => {
                R(ref s, "So you're not what the general public refer to as the\r\ninfamous Reaper of the Bailey?", "Vous n'êtes donc pas ce que le grand public qualifie de\r\ntristement célèbre Faucheur du tribunal ?");
                R(ref s, "Exactly.", "Exactement.");
                R(ref s, "Don't imagine for a moment that the court will be satisfied\r\nwith a one-word answer on this.", "N'espérez pas un instant que ce tribunal se contente\r\nd'une réponse d'un seul mot là-dessus.");
                R(ref s, "I realise that.", "J'en ai conscience.");
                R(ref s, "(If you're intending to comment on every sentence,<E003 8> this\r\ncould take a while, <E003 4>Kazuma...)", "(Si tu comptes commenter chaque phrase,<E003 8> cela risque de\r\nprendre un certain temps, <E003 4>Kazuma...)");
                R(ref s, "Didn't you find it...<E049><E003 12><E025 3>disturbing, though?", "Ne trouviez-vous pas cela...<E049><E003 12><E025 3>troublant, tout de même ?");
                R(ref s, "That one by one, <E049><E003 8><E341>defendants who'd been acquitted after\r\nyour unsuccessful prosecution were killed?", "Le fait qu'un à un, <E049><E003 8><E341>des accusés acquittés à l'issue de vos\r\nprocès infructueux aient été tués ?");
                R(ref s, "Let me answer that question by posing another:", "Permettez-moi de répondre à cette question par une autre :");
                R(ref s, "If, one by one, <E049><E003 8><E025 2>defendants who'd been acquitted after\r\nyour successful defence were killed...", "Si, un par un, <E049><E003 8><E025 2>des accusés acquittés à la suite de vos\r\nplaidoiries victorieuses se faisaient assassiner...");
                R(ref s, "...would you find that ‘disturbing’?", "... trouveriez-vous cela simplement « troublant » ?");
                R(ref s, "Disturbing?!<E049><E003 10> <E025 2>I couldn't possibly say how that would make\r\nme feel with a one-word answer like that!", "Troublant ?!<E049><E003 10> <E025 2>Je serais bien incapable de résumer ce que\r\nj'éprouverais en un simple mot pareil !");
                R(ref s, "(Well...<E003 12>that told me...)", "(Bon...<E003 12>voilà qui remet les pendules à l'heure...)");
                R(ref s, "But even though I'm not the Reaper, <E049><E003 8><E025 2>that doesn't mean I\r\nignored all the hearsay.", "Mais bien que je ne sois pas le Faucheur, <E049><E003 8><E025 2>cela ne signifie\r\npas que j'aie ignoré tous ces bruits de couloir.");
                return s;
            };

            // [82] BB\script\output\_sce04_c303_0040_eng#10
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#10"] = (s) => {
                R(ref s, "You say ‘for years’...<E003 6><E145 1 85><E003 10>\r\n<E025 2>How long exactly?", "Vous dites « depuis des années »...<E003 6><E145 1 85><E003 10>\r\n<E025 2>Depuis combien de temps exactement ?");
                R(ref s, "Since the very first time the Reaper's influence was felt\r\nin this courtroom...<E003 18><E025 3><E145 18 0><E003 8><E330>ten years ago now.", "Depuis la toute première fois où l'ombre du Faucheur a plané\r\nsur cette cour...<E003 18><E025 3><E145 18 0><E003 8><E330>il y a dix ans désormais.");
                R(ref s, "And your investigations led you somehow to Inspector\r\nGregson, <E049><E003 6>you're saying?", "Et vos investigations vous ont mené d'une manière ou d'une\r\nautre à l'inspecteur Gregson, <E049><E003 6>c'est bien cela ?");
                R(ref s, "...I didn't want to believe it.", "... Je refusais d'y croire.");
                R(ref s, "He was a personal acquaintance.<E049><E003 10> We'd worked on cases\r\ntogether in the past.", "C'était une connaissance personnelle.<E049><E003 10> Nous avions instruit\r\ndes affaires de concert par le passé.");
                R(ref s, "(A friend...<E003 10>even?)", "(Un ami...<E003 10>peut-être même ?)");
                R(ref s, "It felt like a betrayal, <E049><E003 8>but...<E003 12><E025 2>I demanded permission to\r\nsearch his office at the Yard without his knowledge.", "J'avais le sentiment d'une trahison, <E049><E003 8>mais...<E003 12><E025 2>j'ai exigé de\r\nfouiller son bureau au Yard à son insu.");
                R(ref s, "Which is <E145 112 13><E118 112 1.5>when you found his secret notebook, <E049><E003 6>is it?", "C'est alors <E145 112 13><E118 112 1.5>que vous avez découvert son carnet secret,<E049><E003 6> n'est-ce pas ?");
                R(ref s, "It's when I first learnt of the location he'd noted only as\r\n‘Grouse’ <E049><E003 10><E025 2>and the appointment at 5 p.m. on the 31st.", "C'est là que j'ai pris connaissance de la mention notée sous le mot\r\n« Grouse » <E049><E003 10><E025 2>et du rendez-vous à 17 h le 31.");
                R(ref s, "Though I didn't know the significance of those details at\r\nthe time.", "Quoique j'ignorasse toute la portée de ces indications à ce moment-là.");
                R(ref s, "(So now we're at the nub of the matter...)", "(Nous touchons donc au nœud du problème...)");
                R(ref s, "As it turns out, <E049><E003 8>the significance for me personally <E049><E003 10><E239>was\r\nvery unfortunate.", "En définitive, <E049><E003 8>ce sens s'est avéré pour moi <E049><E003 10><E239>des plus\r\nfunestes.");
                return s;
            };

            // [83] BB\script\output\_sce04_c303_0040_eng#11
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#11"] = (s) => {
                R(ref s, "But why did you go to that specific location?", "Mais pourquoi vous être rendu à cet endroit précis ?");
                R(ref s, "I thought that if it was the Reaper's headquarters...", "J'ai pensé que s'il s'agissait du repaire du Faucheur...");
                R(ref s, "...then by turning up there at five o'clock, <E049><E003 8>I would catch\r\nwhoever was involved red-handed.", "... en me présentant là-bas sur le coup de cinq heures,<E049><E003 8> je\r\npourrais prendre les complices en flagrant délit.");
                R(ref s, "Sadly, <E049><E003 8><E025 3>all that was awaiting me...", "Hélas, <E049><E003 8><E025 3>tout ce qui m'y attendait...");
                R(ref s, "...was the inspector's corpse.", "... c'était la dépouille de l'inspecteur.");
                R(ref s, "Yes...<E049><E003 10> <E025 2><E333>Even though it wasn't designed for you, <E049><E003 6>you walked\r\nstraight into <E006>the trap<E005> set by Jigoku.", "Oui...<E049><E003 10> <E025 2><E333>Bien qu'il ne vous fût pas destiné, <E049><E003 6>vous êtes\r\ntombé tout droit dans <E006>le piège<E005> tendu par Jigoku.");
                R(ref s, "Jigoku had intended to implicate Hugh Boone.", "Jigoku comptait faire porter le chapeau à Hugh Boone.");
                R(ref s, "But unhappily for me, <E049><E003 10><E239>I arrived at the scene first.", "Mais pour mon plus grand malheur, <E049><E003 10><E239>je suis arrivé le premier.");
                R(ref s, "Hah!<E049><E003 12> <E025 1>A ridiculously careless blunder!", "Ha !<E049><E003 12> <E025 1>Une étourderie d'une impardonnable naïveté !");
                R(ref s, "(Moved on to just throwing insults around, I see then,<E003 6><E341>\r\n<E025 3>Kazuma...)", "(Te voilà réduit à distribuer les insultes à présent,<E003 6><E341>\r\n<E025 3>Kazuma...)");
                R(ref s, "Think what you will.<E049><E003 12>\r\nIt doesn't change the truth.", "Pensez ce que bon vous semble.<E049><E003 12>\r\nCela ne changera rien à la réalité.");
                return s;
            };

            // [84] BB\script\output\_sce04_c303_0040_eng#12
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#12"] = (s) => {
                R(ref s, "There is a link between you and Gregson, though.", "Il existe pourtant bel et bien un lien entre Gregson et vous.");
                R(ref s, "Of course.<E049><E003 10> <E025 2>We were close acquaintances.<E049><E003 12>\r\nWe'd worked on numerous cases together.", "Bien entendu.<E049><E003 10> <E025 2>Nous étions de vieilles connaissances.<E049><E003 12>\r\nNous avons collaboré sur d'innombrables dossiers.");
                R(ref s, "I considered the man to be a mentor of sorts.<E049><E003 12>\r\n<E239><E025 2>He taught me a number of <E006>important lessons<E005>.", "Je le considérais comme une sorte de mentor.<E049><E003 12>\r\n<E239><E025 2>Il m'a enseigné quantité de <E006>leçons fondamentales<E005>.");
                R(ref s, "H-<E049><E003 10>He did?<E049><E003 12>\r\n<E025 2>Such as what?", "V... <E049><E003 10>Vraiment ?<E049><E003 12>\r\n<E025 2>Comme quoi, par exemple ?");
                R(ref s, "Where to buy good fish and chips...<E003 12><E025 3>and suchlike.", "Où acheter un bon fish and chips...<E003 12><E025 3>et autres bagatelles.");
                R(ref s, "(Well...<E003 12>that was convincing.)", "(Eh bien...<E003 12>voilà qui était des plus convaincants.)");
                R(ref s, "Dr Wilson was a coroner, <E049><E003 6>of course, <E049><E003 10><E145 18 2><E118 18 1.1><E025 3>but that was some\r\ntime in the past.", "Le Dr Wilson exerçait la médecine légale, <E049><E003 6>certes, <E049><E003 10><E145 18 2><E118 18 1.1><E025 3>mais c'était\r\nil y a bien longtemps.");
                R(ref s, "And in any case, <E049><E003 10><E025 2>I understand it was several years ago\r\nnow that he was invited to work at a Japanese university.", "Et de toute façon, <E049><E003 10><E025 2>il me semble que c'est il y a des années\r\nqu'il a été invité à enseigner dans une université japonaise.");
                R(ref s, "That's right.<E049><E003 10> <E025 2>He was a visiting professor at the Imperial\r\nYumei University in Tokyo.", "C'est exact.<E049><E003 10> <E025 2>Il était professeur invité à l'université\r\nimpériale de Yumei à Tokyo.");
                R(ref s, "It should be unambiguously clear then, <E049><E003 8><E025 3>that no link exists\r\nbetween myself and him.", "Il devrait donc être parfaitement limpide <E049><E003 8><E025 3>qu'aucun lien n'existe\r\nentre lui et moi.");
                R(ref s, "In other words, <E049><E003 8>I had no motive for sending some assassin\r\nacross the oceans to kill the man.", "Autrement dit, <E049><E003 8>je n'avais nul motif d'envoyer un sicaire\r\nà l'autre bout du monde pour l'abattre.");
                R(ref s, "(It sounds plausible enough, <E003 6><E025 2>and I want to believe it.)", "(Cela paraît tout à fait plausible, <E003 6><E025 2>et j'ai envie d'y croire.)");
                R(ref s, "(But something about this just doesn't quite sit right with\r\nme...)", "(Mais il y a quelque chose là-dedans qui cloche...)");
                return s;
            };

            // [85] BB\script\output\_sce04_c303_0040_eng#13
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#13"] = (s) => {
                R(ref s, "Certainly as it stands, <E049><E003 8><E025 2>there's no evidence to suggest that\r\nyou concocted the scheme.", "Certes, en l'état, <E049><E003 8><E025 2>aucun élément n'indique que vous ayez\r\nconcocté ce complot.");
                R(ref s, "But as it stands, <E049><E003 8>we have only the accused's <E006>insistence<E005> of\r\nhis innocence.", "Mais en l'état, <E049><E003 8>nous n'avons que les <E006>protestations<E005> de l'accusé\r\npour croire en son innocence.");
                R(ref s, "Sorry?!", "Pardon ?!");
                R(ref s, "Perhaps there is some reason that would explain why he\r\nmasterminded the assassin exchange.", "Il existe peut-être une raison qui expliquerait pourquoi il a\r\norganisé cet échange d'assassins.");
                R(ref s, "And if a reason could be established later in these\r\nproceedings...", "Et si une telle raison venait à être établie plus tard au cours\r\nde ces débats...");
                R(ref s, "...then the accused's claim in this testimony that he wasn't\r\ninvolved would amount to <E006>perjury<E005>.", "... alors l'affirmation de l'accusé prétendant n'y être pour rien\r\nconstituerait un <E006>parjure<E005> pur et simple.");
                R(ref s, "Well...<E049><E003 10>yes...<E003 10><E341>that's true, <E049><E003 8>but...", "Eh bien...<E049><E003 10>oui...<E003 10><E341>c'est vrai, <E049><E003 8>mais...");
                R(ref s, "Clearly Kazuma-sama...", "De toute évidence, maître Kazuma...");
                R(ref s, "...intends to identify a reason and use it to make his case.", "... compte bien trouver un mobile pour appuyer sa thèse.");
                R(ref s, "So if we don't identify something first...", "Alors si nous ne trouvons rien les premiers...");
                R(ref s, "...He'll gain the advantage!", "... Il prendra le dessus !");
                R(ref s, "(This could be dangerous...)", "(Cela devient très dangereux...)");
                return s;
            };

            // [86] BB\script\output\_sce04_c303_0040_eng#14
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#14"] = (s) => {
                R(ref s, "(A convincing testimony by Lord van Zieks...)", "(Une déposition convaincante de la part de Lord Van Peers...)");
                R(ref s, "Certainly, <E049><E003 8><E025 2>with no apparent connection between the three\r\nmen, <E049><E003 6>there's no way to establish a motive.", "Certes, <E049><E003 8><E025 2>en l'absence de lien apparent entre ces trois\r\nhommes, <E049><E003 6>impossible d'établir le moindre mobile.");
                R(ref s, "The testimony seems unassailable as far as I can see.", "Sa déposition semble inattaquable pour autant que je puisse en juger.");
                R(ref s, "Oh dear me!<E049><E003 12> <E025 1>What a bleak expression!", "Miséricorde !<E049><E003 12> <E025 1>Quelle mine d'enterrement !");
                R(ref s, "I agree, <E049><E003 8><E025 2>there doesn't appear to be any particular link\r\nbetween them...<E049><E003 12><E025 3>at first glance.", "J'en conviens, <E049><E003 8><E025 2>il ne paraît y avoir aucun lien direct entre\r\neux...<E049><E003 12><E025 3>au premier regard.");
                R(ref s, "But with <E006>the inclusion of one other person<E005>...", "Mais en introduisant <E006>une autre personne<E005> dans l'équation...");
                R(ref s, "(I must be over-thinking it, <E003 4><E025 2>surely...)", "(Je dois sûrement trop me torturer l'esprit...)");
                R(ref s, "Another person, <E049><E003 6>Mr Naruhodo?", "Une autre personne, <E049><E003 6>monsieur Naruhodo ?");
                R(ref s, "I need to think back <E145 9 0>over all the information we've\r\ngleaned so far.", "Il faut que je me remémore <E145 9 0>tous les éléments recueillis\r\njusqu'à maintenant.");
                R(ref s, "Alright.<E049><E003 12> <E333>And I'll review my notes about the case and all\r\nthe evidence in the Court Record!", "D'accord.<E049><E003 12> <E333>Et je vais revoir mes notes et les pièces\r\nà conviction dans le dossier de l'affaire !");
                R(ref s, "(Could it be...<E003 12><E025 3><E341>that Lord van Zieks has something to hide\r\nafter all...?)", "(Se pourrait-il...<E003 12><E025 3><E341>que Lord Van Peers ait réellement quelque chose\r\nà cacher après tout... ?)");
                return s;
            };

            // [87] BB\script\output\_sce04_c303_0040_eng#23
            entryTranslators[@"BB\script\output\_sce04_c303_0040_eng#23"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu suffisamment de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît évident <E049><E003 8><E025 2>que tout débat prolongé sur cette affaire\r\nserait stérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Lord Drake Van Peers, <E049><E003 8><E025 2>j'ose espérer que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "... vous avez néanmoins agi par soif de justice.<E049><E003 12>\r\n<E025 3>Qu'il m'en coûte d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de cette cour, <E049><E003 6><E025 3>je déclare\r\nl'accusé, <E049><E003 6><E025 3>Lord Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "L'audience est levée.<E049><E003 10>\r\n<E025 2>La séance est close !");
                return s;
            };

            // [88] BB\script\output\_sce04_c303_0050_eng#2
            entryTranslators[@"BB\script\output\_sce04_c303_0050_eng#2"] = (s) => {
                R(ref s, "What is this?<E049><E003 16> <E145 61 7><E118 61 0.7><E025 2><E239>An autopsy report?", "Qu'est-ce que ceci ?<E049><E003 16> <E145 61 7><E118 61 0.7><E025 2><E239>Un rapport d'autopsie ?");
                R(ref s, "Wait...<E003 12><E025 2>this is ten years old...<E049><E003 16><E145 61 5><E025 2><E346><E025 1>from the autopsy of Lord Klint\r\nvan Zieks!", "Attendez...<E003 12><E025 2>il date de dix ans...<E049><E003 16><E145 61 5><E025 2><E346><E025 1>de l'autopsie de Lord Klint\r\nVan Peers !");
                R(ref s, "What?!<E049><E003 16>\r\n<E025 2>My brother's autopsy report?!", "Quoi ?!<E049><E003 16>\r\n<E025 2>Le rapport d'autopsie de mon frère ?!");
                R(ref s, "I'm pleased to see <E049><E003 8><E145 112 4><E003 25><E025 2><E333>the defence doesn't intend to run from\r\nthe undeniable truth.", "Je me réjouis de constater que <E049><E003 8><E145 112 4><E003 25><E025 2><E333>la défense n'entend pas fuir\r\nla vérité indéniable.");
                R(ref s, "Order in court!", "Silence dans la salle !");
                R(ref s, "What reason do you have for presenting a ten-year-old\r\nautopsy report here, <E003 4>Counsel?", "Pour quelle raison présentez-vous un rapport d'autopsie vieux\r\nde dix ans devant cette cour, <E003 4>Maître ?");
                R(ref s, "This...<E049><E003 12><E025 2>the autopsy report of the Professor's final victim...", "Ce document...<E049><E003 12><E025 2>le rapport d'autopsie de la dernière victime du Professeur...");
                R(ref s, "...is an indelible link between Inspector Gregson,<E049><E003 10>\r\nDr Wilson...<E049><E003 12><E164 1 8 1 2 8 0 1 1><E139 1><E025 1>and the defendant!", "... constitue le trait d'union indélébile entre l'inspecteur Gregson,<E049><E003 10>\r\nle Dr Wilson...<E049><E003 12><E164 1 8 1 2 8 0 1 1><E139 1><E025 1>et l'accusé !");
                R(ref s, "Not that accursed name again!<E049><E003 14>\r\n<E239><E025 3>The Professor...", "Encore ce maudit nom !<E049><E003 14>\r\n<E239><E025 3>Le Professeur...");
                R(ref s, "I've personally researched all of the court records relating\r\nto that case.", "J'ai personnellement épluché toutes les archives judiciaires liées\r\nà cette affaire.");
                R(ref s, "I know that at the time, <E049><E003 8>autopsy was considered sacrilege\r\nto the victims' souls.", "Je sais qu'à l'époque, <E049><E003 8>l'autopsie passait pour un sacrilège\r\nenvers l'âme des défunts.");
                R(ref s, "And for a member of the aristocracy like Lord Klint van\r\nZieks, <E049><E003 8><E025 3>it was unthinkable.", "Et pour un membre de la haute noblesse tel que Lord Klint\r\nVan Peers, <E049><E003 8><E025 3>c'était tout bonnement impensable.");
                R(ref s, "But someone implored the powers that be to allow the\r\nautopsy to go ahead:<E049><E003 12> <E025 3>Inspector Gregson.", "Mais quelqu'un a supplié les hautes autorités d'autoriser la\r\npratique de cette autopsie :<E049><E003 12> <E025 3>l'inspecteur Gregson.");
                R(ref s, "He declared that he was certain <E049><E003 12><E025 3><E330>he would obtain\r\nconclusive proof from the procedure.", "Il affirmait avoir l'intime certitude <E049><E003 12><E025 3><E330>qu'elle fournirait une\r\npreuve irréfutable.");
                R(ref s, "And <E171 1 16 0 10 2>it was Dr Wilson who conducted the autopsy.", "Et <E171 1 16 0 10 2>c'est le Dr Wilson qui a mené cette autopsie.");
                R(ref s, "His signature <E049><E003 10><E333>is clearly visible on the document!", "Sa signature <E049><E003 10><E333>y est parfaitement visible !");
                R(ref s, "As promised by Gregson, <E049><E003 10><E145 18 0><E118 18 1.5><E003 8><E025 3>the autopsy did indeed produce\r\nevidence.", "Comme l'avait promis Gregson, <E049><E003 10><E145 18 0><E118 18 1.5><E003 8><E025 3>l'autopsie a bel et bien mis au jour\r\nune preuve.");
                R(ref s, "Evidence that conclusively proved Genshin Asogi was\r\nguilty of the murders.", "Une preuve qui établissait de manière irrévocable la culpabilité\r\nde Genshin Asogi pour ces meurtres.");
                R(ref s, "In my brother's dying moments, <E049><E003 8><E025 2>he mustered all his\r\nremaining strength to leave that vital clue behind.", "Dans ses derniers instants, <E049><E003 8><E025 2>mon frère a rassemblé ses\r\ndernières forces pour laisser cet indice vital.");
                R(ref s, "Indeed.<E049><E003 12> <E025 2>That was the key to indicting the Professor for his\r\ncrimes and the conclusive evidence that convicted him.", "En effet.<E049><E003 12> <E025 2>Ce fut la clé pour inculper le Professeur pour ses\r\nforfaits et la preuve concluante qui le fit condamner.");
                R(ref s, "It enabled Lord van Zieks here to avenge his brother's\r\nsenseless death...<E049><E003 10><E145 61 4><E118 61 0.8><E025 3>with a marvellous victory in court.", "Elle a permis à Lord Van Peers ici présent de venger la mort injuste\r\nde son frère...<E049><E003 10><E145 61 4><E118 61 0.8><E025 3>par une éclatante victoire judiciaire.");
                R(ref s, "A marvellous victory, <E049><E003 8><E025 3>was it?", "Une éclatante victoire, <E049><E003 8><E025 3>vraiment ?");
                R(ref s, "I wonder if that's really true.", "Je me demande si c'est réellement le cas.");
                R(ref s, "What?", "Quoi ?");
                R(ref s, "Could the same be said if it turned out <E049><E003 8><E330>that the key piece\r\nof evidence in question was in fact <E006>fabricated<E005>?", "En dirait-on autant s'il s'avérait <E049><E003 8><E330>que la preuve maîtresse\r\nen question a en vérité été de toutes pièces <E006>fabriquée<E005> ?");
                R(ref s, "If the inspector, <E049><E003 8>the coroner <E049><E003 6>and the prosecutor all\r\ncolluded together...", "Si l'inspecteur, <E049><E003 8>le légiste <E049><E003 6>et le procureur ont tous\r\ncomploté de concert...");
                R(ref s, "...to cast an innocent Japanese man as a mass murderer\r\nand send him to his death!", "... pour faire passer un Japonais innocent pour un tueur en série\r\net l'envoyer à la potence !");
                R(ref s, "That's <E341>outrageous!", "C'est <E341>infâme !");
                R(ref s, "And now, <E049><E003 10>ten years later, <E049><E003 10><E025 2>for some reason the secret has\r\nbeen threatened and needs protecting.", "Et aujourd'hui, <E049><E003 10>dix ans après, <E049><E003 10><E025 2>ce secret menaçait d'éclater\r\net devait être protégé.");
                R(ref s, "Which is why the inspector and the coroner had to be\r\nsilenced...<E049><E003 10>isn't it?", "Voilà pourquoi l'inspecteur et le médecin légiste devaient être\r\nréduits au silence...<E049><E003 10>n'est-ce pas ?");
                R(ref s, "By someone in power in Japan and in Britain...<E049><E003 14><E025 1><E164 112 10 1 2 5 1 1 1><E139 112>using the\r\ntwo killers recruited for the assassin exchange!", "Par un homme de pouvoir au Japon et en Grande-Bretagne...<E049><E003 14><E025 1><E164 112 10 1 2 5 1 1 1><E139 112>à l'aide\r\ndes deux tueurs engagés pour cet échange d'assassins !");
                R(ref s, "Order!<E003 5> <E025 1>Order at once!", "Silence !<E003 5> <E025 1>Silence immédiat !");
                R(ref s, "Ten years ago, <E049><E003 12><E025 3>my father was convicted in this very\r\ncourtroom as a mass murderer...<E003 12><E025 3>to be sentenced to death.", "Il y a dix ans, <E049><E003 12><E025 3>mon père a été condamné dans ce prétoire\r\nmême comme un tueur sanguinaire...<E003 12><E025 3>et voué à la mort.");
                R(ref s, "But it was all a sham!<E049><E003 12>\r\n<E025 2>And I swore to myself that I'd prove it.", "Mais tout cela n'était qu'une infâme mascarade !<E049><E003 12>\r\n<E025 2>Et j'ai juré sur mon honneur de le prouver.");
                R(ref s, "Which is why I HAD to come to Britain...<E049><E003 20><E164 112 7 1 2 5 0 3 1><E139 112>\r\n<E025 1>whatever the cost!", "Voilà pourquoi je DEVAIS venir en Angleterre...<E049><E003 20><E164 112 7 1 2 5 0 3 1><E139 112>\r\n<E025 1>coûte que coûte !");
                R(ref s, "You'll have to forgive me <E049><E003 8><E025 2>if I feel compelled to toast this\r\nvengeful Nipponese's tenacity of purpose here.", "Pardonnez-moi <E049><E003 8><E025 2>si je me sens contraint de lever mon verre à la\r\nténacité vengeresse de ce sujet nippon.");
                R(ref s, "However...", "Cependant...");
                R(ref s, "...he who fails to quash his emotions in the courtroom...<E049><E003 12>\r\n<E025 3>has failed as a lawyer.", "... quiconque ne sait point dompter ses émotions en cour...<E049><E003 12>\r\n<E025 3>a d'ores et déjà échoué en tant qu'homme de loi.");
                R(ref s, "Come on, Kazuma!<E049><E003 14>\r\n<E341><E025 1>You know this won't wash!", "Voyons, Kazuma !<E049><E003 14>\r\n<E341><E025 1>Tu sais bien que cela ne tient pas la route !");
                R(ref s, "You're claiming your father was misrepresented in a trial\r\nthat took place a whole decade ago!", "Tu prétends que ton père a été victime d'un coup monté lors\r\nd'un procès vieux de dix ans !");
                R(ref s, "You must see that without evidence, <E049><E003 2><E025 1><E164 1 71 1 2 8 0 2 1><E139 1>that's nothing more\r\nthan a wild accusation!", "Tu dois comprendre que sans preuve, <E049><E003 2><E025 1><E164 1 71 1 2 8 0 2 1><E139 1>ce n'est rien d'autre\r\nqu'une accusation délirante !");
                R(ref s, "As it happens...<E049><E003 20><E145 112 6><E118 112 0.7><E003 12><E025 3><E238>I have evidence.", "Il se trouve que...<E049><E003 20><E145 112 6><E118 112 0.7><E003 12><E025 3><E238>j'ai une preuve.");
                R(ref s, "WHAT?!", "QUOI ?!");
                return s;
            };

            // [89] BB\script\output\_sce04_c304_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c304_0000_eng#2"] = (s) => {
                R(ref s, "As the court has heard, <E049><E003 8><E025 2>I crossed the Channel to France\r\nwith Gregson on the 31st.", "Comme la cour l'a entendu, <E049><E003 8><E025 2>j'ai traversé la Manche vers la\r\nFrance avec Gregson le 31.");
                R(ref s, "I went with him on the pretext of being the assassin\r\nrecruited to kill Seishiro Jigoku.", "Je suis parti avec lui sous le prétexte d'être le sicaire\r\nchargé d'abattre Seishiro Jigoku.");
                R(ref s, "But my true intentions...<E049><E003 4><E145 112 0><E118 112 1.4><E003 15><E025 3>were to make the inspector tell\r\nme the truth.", "Mais ma réelle intention...<E049><E003 4><E145 112 0><E118 112 1.4><E003 15><E025 3>était de contraindre l'inspecteur\r\nà m'avouer la vérité.");
                R(ref s, "What truth?", "Quelle vérité ?");
                R(ref s, "The truth about the evidence.<E049><E003 15> <E025 2>And he acknowledged what\r\nI'd already deduced:", "La vérité sur cette pièce à conviction.<E049><E003 15> <E025 2>Et il a reconnu ce que\r\nj'avais déjà déduit :");
                R(ref s, "There's <E006>a closely guarded secret<E005> <E049><E003 10><E146 112 4>about what went on in\r\nthat autopsy ten years ago.", "Il y a <E006>un secret farouchement gardé<E005> <E049><E003 10><E146 112 4>concernant ce qui s'est\r\npassé lors de cette autopsie il y a dix ans.");
                R(ref s, "What? <E049><E003 16><E331>A secret?<E049><E003 16>\r\n<E025 1><E335>...I know nothing of any secret!", "Quoi ? <E049><E003 16><E331>Un secret ?<E049><E003 16>\r\n<E025 1><E335>... Je ne sais rien d'un quelconque secret !");
                R(ref s, "While we waited for my supposed ‘mark’ in Jigoku's\r\ncabin...", "Pendant que nous attendions ma prétendue « cible » dans la cabine\r\nde Jigoku...");
                R(ref s, "...I drew my clan's illustrious sword, Karuma, <E049><E003 8>before the\r\ninspector's eyes.", "... j'ai dégainé le sabre illustre de mon clan, Karuma, <E049><E003 8>sous les yeux\r\nde l'inspecteur.");
                R(ref s, "He very quickly understood what my true motive was.", "Il a très vite compris quel était mon véritable dessein.");
                R(ref s, "Right, <E049><E003 6>I see...<E049><E003 12> <E025 2>You're that Asogi's young lad, <E049><E003 6>are you?", "Bien, <E049><E003 6>je vois...<E049><E003 12> <E025 2>Vous êtes le p'tit gars d'Asogi, <E049><E003 6>c'est ça ?");
                R(ref s, "And what?<E049><E003 10> You're gonna cut me down with that thing, <E049><E003 6>is\r\nthat it?", "Et alors ?<E049><E003 10> Vous allez m'trancher avec vot' fer, <E049><E003 6>c'est\r\nça l'idée ?");
                R(ref s, "That will very much depend on the answers you give to\r\nmy questions.", "Cela dépendra entièrement des réponses que vous fournirez à\r\nmes questions.");
                R(ref s, "I want to know what really happened ten years ago.", "Je veux savoir ce qui s'est réellement passé il y a dix ans.");
                R(ref s, "The truth.<E003 12> That's all.", "La vérité.<E003 12> Rien d'autre.");
                R(ref s, "Before we get into it, <E049><E003 8>let me make one thing clear:", "Avant qu'on commence, <E049><E003 8>mettons une chose au clair :");
                R(ref s, "I still believe your father was the Professor.<E049><E003 10>\r\n<E025 3>There's no doubt in my mind.", "Je suis toujours convaincu que vot' père était le Professeur.<E049><E003 10>\r\n<E025 3>Y a pas le moindre doute dans mon esprit.");
                R(ref s, "But unfortunately back then...<E049><E003 10><E145 7 68><E003 15><E330>we didn't have the evidence\r\nwe needed to make the crime stick.", "Mais par malheur à l'époque...<E049><E003 10><E145 7 68><E003 15><E330>on n'avait pas les preuves\r\nqu'il fallait pour le faire condamner.");
                R(ref s, "So...<E003 12><E025 3>you admit it then?", "Alors...<E003 12><E025 3>vous l'admettez donc ?");
                R(ref s, "The evidence used in my father's trial <E003 12><E025 1><E046>was <E006>fabricated<E005>?!", "La preuve utilisée au procès de mon père <E003 12><E025 1><E046>a été <E006>fabriquée<E005> ?!");
                R(ref s, "It was for the good o' the country.", "C'était pour le bien du pays.");
                return s;
            };

            // [90] BB\script\output\_sce04_c304_0000_eng#3
            entryTranslators[@"BB\script\output\_sce04_c304_0000_eng#3"] = (s) => {
                R(ref s, "Anyway...<E049><E003 20><E025 3><E333>I was just followin' orders.", "De toute façon...<E049><E003 20><E025 3><E333>j'n'ai fait qu'obéir aux ordres.");
                R(ref s, "Orders?<E003 20>\r\n<E046><E025 1>What exactly did you do?<E003 16> <E346><E025 1>...Speak!", "Des ordres ?<E003 20>\r\n<E046><E025 1>Qu'avez-vous fait exactement ?<E003 16> <E346><E025 1>... Parlez !");
                R(ref s, "I'm not sayin' another word.", "J'dirai pas un mot de plus.");
                R(ref s, "Even if your life depends on it?", "Même si votre vie en dépend ?");
                R(ref s, "That's right.<E049><E003 20>\r\n<E025 3><E239>Even then.", "C'est exact.<E049><E003 20>\r\n<E025 3><E239>Même dans c'cas.");
                R(ref s, "*Shing!*", "*Schling !*");
                return s;
            };

            // [91] BB\script\output\_sce04_c304_0000_eng#4
            entryTranslators[@"BB\script\output\_sce04_c304_0000_eng#4"] = (s) => {
                R(ref s, "So that's when the tip of the sword broke...", "C'est donc là que la pointe de la lame s'est brisée...");
                R(ref s, "Oh, <E049><E003 8>Kazuma-sama...", "Oh, <E049><E003 8>maître Kazuma...");
                R(ref s, "If the results of Klint van Zieks's autopsy were\r\n<E006>fabricated<E005>...", "Si les conclusions de l'autopsie de Klint Van Peers ont été\r\n<E006>fabriquées de toutes pièces<E005>...");
                R(ref s, "...then the investigating officer, Gregson, <E049><E003 8>and the lead\r\ncoroner, Wilson, <E049><E003 8><E025 3>must have known about it.", "... alors l'officier enquêteur, Gregson, <E049><E003 8>et le médecin légiste\r\nen chef, Wilson, <E049><E003 8><E025 3>étaient obligatoirement au courant.");
                R(ref s, "And they can only have been ordered to pervert the\r\ncourse of justice in that way by one man:", "Et ils n'ont pu recevoir l'ordre d'entraver le cours de la justice\r\nde cette manière que d'un seul homme :");
                R(ref s, "The man leading the case for <E006>the prosecution<E005>,<E049><E003 15> <E025 2><E238>Barok van\r\nZieks!", "L'homme qui dirigeait l'accusation au procès, <E049><E003 15><E025 2><E238>Lord Drake\r\nVan Peers !");
                R(ref s, "In other words, <E049><E003 15><E145 61 10><E003 20><E025 3>the defendant DID have cause to organise<E049><E003 6><E164 61 12 1 2 8 0 1 1><E118 61 1.3><E139 61>\r\n<E025 1>this exchange of assassins!", "En d'autres termes, <E049><E003 15><E145 61 10><E003 20><E025 3>le prévenu AVAIT un motif d'organiser<E049><E003 6><E164 61 12 1 2 8 0 1 1><E118 61 1.3><E139 61>\r\n<E025 1>cet échange d'assassins !");
                R(ref s, "And as was established earlier...", "Et comme il a été établi plus tôt...");
                R(ref s, "...it has to have been <E006>the Reaper himself<E005> who liaised with\r\nJigoku in Japan to arrange the exchange.", "... ce ne peut être que <E006>le Faucheur en personne<E005> qui a contacté\r\nJigoku au Japon pour négocier cet échange.");
                R(ref s, "So it follows that the Reaper's true identity...", "Il s'ensuit donc que la véritable identité du Faucheur...");
                R(ref s, "...can only be that of the man who stands accused in this\r\ncourtroom today, <E049><E003 12><E607><E025 1>Barok van Zieks!", "... ne peut être que celle de l'homme assis sur le banc des\r\naccusés aujourd'hui, <E049><E003 12><E607><E025 1>Lord Drake Van Peers !");
                R(ref s, "Kazuma Asogi...", "Kazuma Asogi...");
                R(ref s, "...What?", "... Quoi ?");
                R(ref s, "What you've just told the court...<E049><E003 15>\r\n<E025 2><E341>Are you absolutely certain of your facts?", "Ce que vous venez de conter à la cour...<E049><E003 15>\r\n<E025 2><E341>Êtes-vous absolument sûr de vos affirmations ?");
                R(ref s, "Did Gregson <E049><E003 14><E164 18 13 1 2 9 0 2 1><E118 18 1.2><E139 18><E025 1>really fabricate evidence for that trial ten\r\nyears ago?", "Gregson a-t-il <E049><E003 14><E164 18 13 1 2 9 0 2 1><E118 18 1.2><E139 18><E025 1>véritablement forgé des preuves pour ce\r\nprocès il y a dix ans ?");
                R(ref s, "I heard it with my own ears.<E049><E003 10><E145 112 14><E003 10>\r\n<E025 3>His shameful admission.", "Je l'ai entendu de mes propres oreilles.<E049><E003 10><E145 112 14><E003 10>\r\n<E025 3>Ses aveux honteux.");
                R(ref s, "In that case...<E003 12>I know...", "En ce cas...<E003 12>je connais...");
                R(ref s, "...the name of the Reaper.", "... le nom du Faucheur.");
                R(ref s, "Wha...<E049><E003 8><E025 3><E145 112 7><E118 112 0.75><E139 112><E338><E342><E025 1>What?", "Qu... <E049><E003 8><E025 3><E145 112 7><E118 112 0.75><E139 112><E338><E342><E025 1>Quoi ?");
                R(ref s, "Lord van Zieks?", "Lord Van Peers ?");
                R(ref s, "I gave no such orders.<E049><E003 14>\r\nI know that for certain.", "Je n'ai jamais donné de tels ordres.<E049><E003 14>\r\nJ'en suis absolument certain.");
                R(ref s, "Which narrows down the remaining possibilities...<E049><E003 8><E025 1><E164 18 13 1 2 5 0 2 1><E118 18 1.3><E139 18>to one!", "Ce qui réduit les possibilités restantes...<E049><E003 8><E025 1><E164 18 13 1 2 5 0 2 1><E118 18 1.3><E139 18>à une seule !");
                R(ref s, "(If Lord van Zieks isn't the one behind all this...)", "(Si Lord Van Peers n'est pas le cerveau de tout ceci...)");
                R(ref s, "(...then yes, <E003 12><E025 2><E341><E338>there is only one other person who could\r\nhave done something like that.)", "(... alors oui, <E003 12><E025 2><E341><E338>il n'existe qu'une seule personne capable\r\nd'une telle manœuvre.)");
                R(ref s, "I believe I know who it is, too.", "Je crois que je sais de qui il s'agit, moi aussi.");
                R(ref s, "You...?!", "Toi... ?!");
                return s;
            };

