            // [94] BB\script\output\_sce04_c304_0010_eng#4
            entryTranslators[@"BB\script\output\_sce04_c304_0010_eng#4"] = (s) => {
                R(ref s, "(It's really palpable now...)", "(La tension est vraiment palpable désormais...)");
                R(ref s, "(That overwhelming pressure <E003 10><E330><E025 2>that's making it almost\r\nimpossible to speak before this gargantuan foe...)", "(Cette écrasante pression <E003 10><E330><E025 2>qui rend presque impossible\r\nde parler face à un adversaire aussi monumental...)");
                R(ref s, "(But I can't back away now.<E003 12> <E025 1><E338><E341>There's no time!)", "(Mais je ne peux plus reculer.<E003 12> <E025 1><E338><E341>C'est maintenant ou jamais !)");
                R(ref s, "What's the matter, Counsel?<E049><E003 10>\r\nI take exception at the look you're giving me.", "Qu'y a-t-il, Maître ?<E049><E003 10>\r\nJe m'offusque du regard que vous me portez.");
                R(ref s, "I was...<E049><E003 12><E025 2>just gathering my thoughts.<E049><E003 14>\r\n<E025 1><E346>I'm ready to voice the defence's opinion now.", "J'étais...<E049><E003 12><E025 2>en train de rassembler mes pensées.<E049><E003 14>\r\n<E025 1><E346>La défense est prête à exprimer sa conclusion.");
                R(ref s, "Very well.", "Très bien.");
                R(ref s, "But before you do...<E003 12><E025 3>a penalty for time-wasting.", "Mais avant cela...<E003 12><E025 3>une pénalité pour perte de temps.");
                R(ref s, "Uuugh...", "Argh...");
                R(ref s, "Ryunosuke...", "Ryunosuke...");
                R(ref s, "Counsel for the Defence, <E049><E003 8>reveal your belief about the\r\nidentity of the Reaper...", "Maître pour la défense, <E049><E003 8>révélez qui se cache selon vous\r\nderrière l'identité du Faucheur...");
                R(ref s, "...if you have the courage and the resolve to utter the\r\nname, <E049><E003 8><E025 3>that is.", "... si du moins vous avez le courage et la résolution d'en\r\nprononcer le nom.");
                return s;
            };

            // [95] BB\script\output\_sce04_c304_0010_eng#5
            entryTranslators[@"BB\script\output\_sce04_c304_0010_eng#5"] = (s) => {
                R(ref s, "The only person who could have arranged the assassin\r\nexchange and manipulated the autopsy results...", "La seule personne qui pouvait organiser cet échange d'assassins\r\net manipuler les conclusions d'autopsie...");
                R(ref s, "...is the Lord Chief Justice himself...", "... n'est autre que le Lord juge en chef lui-même...");
                R(ref s, "...Lord Mael Stronghart!", "... Lord Mael Stronghart !");
                R(ref s, "Wha...?!<E049><E003 18>\r\n<E025 3><E338><E341>Lord...<E003 12><E025 2>Stronghart...?", "Qu... Quoi ?!<E049><E003 18>\r\n<E025 3><E338><E341>Lord...<E003 12><E025 2>Stronghart... ?");
                R(ref s, "Yes, <E049><E003 8><E025 2>it's true that ten years ago, <E049><E003 8>the defendant handled the\r\nprosecution of the Professor in court.", "Oui, <E049><E003 8><E025 2>il est exact qu'il y a dix ans, <E049><E003 8>l'accusé a soutenu\r\nl'accusation contre le Professeur.");
                R(ref s, "But he only took over the case <E006>after<E005> his brother,<E049><E003 6> Lord\r\nKlint van Zieks, had been killed.", "Mais il n'a repris le dossier <E006>qu'après<E005> que son frère,<E049><E003 6> Lord\r\nKlint Van Peers, a été assassiné.");
                R(ref s, "I can only assume that this is the most inappropriate joke\r\nin British judicial history.", "Je ne puis que supposer qu'il s'agit de la plaisanterie la plus\r\ndéplacée de toute l'histoire judiciaire britannique.");
                R(ref s, "Well, <E049><E003 8>Lord van Zieks?", "Alors, <E049><E003 8>Lord Van Peers ?");
                R(ref s, "...Ten years ago...<E049><E003 14>I was very new to my profession.", "... Il y a dix ans...<E049><E003 14>j'étais tout nouveau dans la profession.");
                R(ref s, "But I had a burning desire to avenge my brother's death,<E049><E003 10>\r\n<E239>so I pleaded for control of the case.", "Mais j'étais animé du brûlant désir de venger mon frère,<E049><E003 10>\r\n<E239>alors j'ai supplié qu'on me confie l'affaire.");
                R(ref s, "The investigation to that point...<E049><E003 12> The supplication of the\r\nLords to allow my brother's corpse to be examined...", "L'enquête menée jusque-là...<E049><E003 12> La supplique auprès des Lords\r\npour autoriser l'examen de sa dépouille...");
                R(ref s, "All the evidence I was given...<E003 12> The autopsy reports...<E003 14>\r\nIt all came...<E003 6><E145 18 3><E118 18 0.5><E003 12><E025 3><E333>from you.", "Toutes les preuves que l'on m'a remises...<E003 12> Le rapport d'autopsie...<E003 14>\r\nTout cela venait...<E003 6><E145 18 3><E118 18 0.5><E003 12><E025 3><E333>de vous.");
                R(ref s, "I've spent my life since then believing I was in your debt\r\nfor the way you stood aside and let me handle the trial.", "J'ai passé mon existence depuis lors à me croire votre débiteur\r\npour m'avoir cédé votre place et laissé conduire ce procès.");
                R(ref s, "But I see now...", "Mais je réalise à présent...");
                R(ref s, "...I was very much mistaken.", "... que je m'abusais lourdement.");
                R(ref s, "It was <E006>a hugely influential force<E005> that caused the inspector\r\nand the coroner to break the law ten years ago.", "C'est <E006>une force prodigieusement influente<E005> qui a poussé l'inspecteur\r\net le légiste à enfreindre la loi il y a dix ans.");
                R(ref s, "And that same force was still felt a decade later on the\r\nother side of the world...<E003 12>by Seishiro Jigoku.", "Et cette même influence s'est fait sentir une décennie plus tard\r\nà l'autre bout du monde...<E003 12>sur Seishiro Jigoku.");
                R(ref s, "Lord Stronghart!", "Lord Stronghart !");
                R(ref s, "Everything falls into place when we recognise that you...<E049><E003 12><E164 1 8 1 2 8 0 1 1><E139 1>\r\n<E025 1>are the Reaper of the Bailey!", "Toutes les pièces s'emboîtent dès lors que l'on admet que vous...<E049><E003 12><E164 1 8 1 2 8 0 1 1><E139 1>\r\n<E025 1>êtes le Faucheur du tribunal !");
                R(ref s, "The court awaits your response...<E049><E003 12><E025 3>My Lord.", "La cour attend votre réponse...<E049><E003 12><E025 3>Votre Grâce.");
                R(ref s, "This may very well go down in British judicial history,<E049><E003 10>\r\nbut I assure you...<E003 12><E025 3>it is no joke.", "Cela marquera très certainement l'histoire judiciaire de l'Empire,<E049><E003 10>\r\nmais je vous assure...<E003 12><E025 3>que cela n'a rien d'une plaisanterie.");
                R(ref s, "Consider this <E049><E003 12><E145 18 26><E117 18 6><E607><E025 1>a formal <E006>accusal<E005> by the defence!", "Considérez ceci <E049><E003 12><E145 18 26><E117 18 6><E607><E025 1>comme une <E006>mise en accusation<E005> formelle par la défense !");
                R(ref s, "It doesn't warrant a response.", "Cela ne mérite même pas de réponse.");
                R(ref s, "A formal accusal?<E049><E003 20>\r\n<E025 2><E341><E338>Don't be absurd.", "Une mise en accusation formelle ?<E049><E003 20>\r\n<E025 2><E341><E338>Ne soyez pas ridicule.");
                R(ref s, "The defence's claims are utter nonsense.<E049><E003 12>\r\n<E345><E342><E025 1>A wild fantasy at best.", "Les prétentions de la défense sont de pures inepties.<E049><E003 12>\r\n<E345><E342><E025 1>Un délire fantasque tout au plus.");
                R(ref s, "...You're not going to defend yourself?", "... Vous refusez de vous défendre ?");
                R(ref s, "You claim there was some wrongdoing with Lord Klint\r\nvan Zieks's autopsy?", "Vous prétendez qu'il y a eu des malversations lors de l'autopsie\r\nde Lord Klint Van Peers ?");
                R(ref s, "That's utterly untrue.", "C'est rigoureusement faux.");
                R(ref s, "But I heard it from Gregson's own lips!<E049><E003 16>\r\n<E346>He admitted to it!", "Mais je l'ai entendu de la bouche même de Gregson !<E049><E003 16>\r\n<E346>Il l'a avoué !");
                R(ref s, "...And where is your evidence?", "... Et où sont vos preuves ?");
                R(ref s, "Gregson's dead now.<E049><E003 12> Unless you were thinking of\r\nsummoning a ghost to the stand?", "Gregson est mort.<E049><E003 12> À moins que vous ne comptiez citer un fantôme\r\nà la barre des témoins ?");
                R(ref s, "You, <E049><E003 8><E338><E342>you mean to say...?", "Vous... <E049><E003 8><E338><E342>vous insinuez que... ?");
                R(ref s, "I forget how the system works in your little backwater\r\ncountry...", "J'ignore comment fonctionne la justice dans votre lointaine\r\ncontrée arriérée...");
                R(ref s, "...but in the courts of the British Empire, <E049><E003 8><E025 3>without\r\nevidence, <E049><E003 6>there is no case.", "... mais dans les tribunaux de l'Empire britannique, <E049><E003 8><E025 3>sans\r\npreuves, <E049><E003 6>il n'y a pas d'accusation qui tienne.");
                R(ref s, "I have no intention of entertaining some <E006>wild fantasy<E005> that\r\ncan't possibly be substantiated by anyone or anything!", "Je refuse d'accorder le moindre crédit à un <E006>délire insensé<E005> qui\r\nne repose sur aucun élément tangible !");
                R(ref s, "AAAAAAAAARGH", "AAAAAAAAARGH");
                R(ref s, "Order!<E003 5> <E025 1>Order in court!", "Silence !<E003 5> <E025 1>Silence dans ce tribunal !");
                R(ref s, "Following Inspector Gregson's murder and in the light of\r\nDr Wilson's death as well...", "Après l'assassinat de l'inspecteur Gregson et compte tenu du\r\ndécès du Dr Wilson également...");
                R(ref s, "...there's really no one left who could testify about the\r\nevents of ten years ago...<E003 12><E025 3>is there?", "... il ne reste absolument personne pour témoigner des faits\r\nsurvenus il y a dix ans...<E003 12><E025 3>n'est-ce pas ?");
                R(ref s, "So that was <E006>the real purpose<E005> of the assassin exchange...", "C'était donc là <E006>le véritable dessein<E005> de cet échange d'assassins...");
                R(ref s, "This court has no business raking over the coals of a case\r\nthat was concluded a decade ago.", "Cette cour n'a point à remuer les cendres d'une affaire close\r\ndepuis dix années.");
                R(ref s, "The accusal brought by the prosecution and the defence<E049><E003 14>\r\n<E025 1><E332>is categorically denied.", "L'accusation formulée par le parquet et la défense<E049><E003 14>\r\n<E025 1><E332>est catégoriquement rejetée.");
                R(ref s, "I take it there are no objections?", "J'ose espérer qu'il n'y a nulle objection ?");
                return s;
            };

            // [96] BB\script\output\_sce04_c304_0010_eng#6
