            // [103] BB\script\output\_sce04_c304_0030_eng#4
            entryTranslators[@"BB\script\output\_sce04_c304_0030_eng#4"] = (s) => {
                R(ref s, "Denied.", "Refusé.");
                R(ref s, "What?!<E049><E003 8> <E164 1 71 1 2 1 0 2 1><E139 1><E025 1>I want to know why!", "Comment ?!<E049><E003 8> <E164 1 71 1 2 1 0 2 1><E139 1><E025 1>J'exige de savoir pourquoi !");
                R(ref s, "And I want to know why you're proposing to call such a\r\nwitness with that look of utter desperation on your face.", "Et j'aimerais savoir pourquoi vous proposez d'appeler ce témoin\r\navec un regard aussi désespéré.");
                R(ref s, "In other words, <E049><E003 12><E025 2><E333>you're <E006>wide of the mark<E005>, <E049><E003 6><E025 3>Ryunosuke.<E049><E003 14>\r\n<E025 2><E341>Very wide.", "En d'autres termes, <E049><E003 12><E025 2><E333>tu es <E006>complètement à côté de la plaque<E005>, <E049><E003 6><E025 3>Ryunosuke.<E049><E003 14>\r\n<E025 2><E341>Complètement.");
                R(ref s, "(Thanks.<E003 10> Don't spare my feelings or anything...)", "(Merci.<E003 10> Surtout, ne ménage pas mes sentiments...)");
                R(ref s, "Given the contemptible allegations you're making,<E049><E003 8>\r\nCounsel, <E049><E003 8><E145 61 5><E144 61><E025 2><E341>I won't be letting that blunder pass unpunished.", "Eu égard aux allégations outrageantes que vous proférez,<E049><E003 8>\r\nMaître, <E049><E003 8><E145 61 5><E144 61><E025 2><E341>je ne laisserai pas cet impair impuni.");
                R(ref s, "Uuugh...", "Argh...");
                R(ref s, "There was somebody else present at the autopsy,<E049><E003 6>\r\nMr Naruhodo.<E049><E003 12> <E025 1><E335>Surely you haven't forgotten?", "Il y avait quelqu'un d'autre présent lors de l'autopsie,<E049><E003 6>\r\nmonsieur Naruhodo.<E049><E003 12> <E025 1><E335>Vous n'avez tout de même pas oublié ?");
                R(ref s, "No, <E003 8>I...<E003 10>I know.<E003 14>\r\n<E025 1><E346>I'll get it right this time!", "Non, <E003 8>je...<E003 10>je sais.<E003 14>\r\n<E025 1><E346>Je ne me tromperai pas cette fois !");
                return s;
            };

            // [104] BB\script\output\_sce04_c304_0030_eng#5
            entryTranslators[@"BB\script\output\_sce04_c304_0030_eng#5"] = (s) => {
                R(ref s, "Heaven help us.<E049><E003 15><E145 61 4><E118 61 0.5>\r\n<E025 3>Another Japanese?", "Grand Dieu tout-puissant.<E049><E003 15><E145 61 4><E118 61 0.5>\r\n<E025 3>Encore un Japonais ?");
                R(ref s, "An expert in forensic medicine, <E049><E003 6>My Lord.<E049><E003 12>\r\n<E025 3>Professor Yujin Mikotoba.<E049><E003 10> <E025 2>Sixteen years ago...", "Un éminent spécialiste de médecine légale, <E049><E003 6>Votre Honneur.<E049><E003 12>\r\n<E025 3>Le professeur Yujin Mikotoba.<E049><E003 10> <E025 2>Il y a seize ans...");
                R(ref s, "...he came to London with Seishiro Jigoku and Genshin\r\nAsogi as a visiting student.", "... il est venu à Londres en compagnie de Seishiro Jigoku et\r\nGenshin Asogi en tant qu'étudiant étranger.");
                R(ref s, "And what could his testimony possibly tell us?", "Et que pourrait bien nous apprendre sa déposition ?");
                R(ref s, "Professor Mikotoba <E171 1 16 0 10 2>was the primary assistant during the\r\nautopsy in question.", "Le professeur Mikotoba <E171 1 16 0 10 2>était l'assistant principal lors de\r\nl'autopsie en question.");
                R(ref s, "He was also <E049><E003 12><E025 1><E346>the person who actually penned the report!", "Il est également <E049><E003 12><E025 1><E346>la personne qui a rédigé le rapport !");
                R(ref s, "Incorrect.<E049><E003 15> <E025 2>The autopsy was carried out by the coroner,<E049><E003 8>\r\nDr Wilson.<E049><E003 12> The report carries his signature.", "C'est inexact.<E049><E003 15> <E025 2>L'autopsie a été exécutée par le médecin légiste,<E049><E003 8>\r\nle Dr Wilson.<E049><E003 12> Le rapport porte sa signature.");
                R(ref s, "It was the primary assistant's duty to keep a written\r\nrecord of the coroner's work during the procedure.", "Le rôle de l'assistant principal était de consigner par écrit les\r\nconstatations du légiste au fil de l'opération.");
                R(ref s, "In actual fact, <E049><E003 10><E333><E025 2>the coroner merely read over the report at\r\nthe end and signed it.", "En réalité, <E049><E003 10><E333><E025 2>le légiste s'est borné à relire le rapport\r\nà la fin et à y apposer son paraphe.");
                R(ref s, "In other words, <E049><E003 6><E145 1 0><E118 1 0.5><E003 10><E025 2>Professor Mikotoba witnessed <E006>the entire\r\nautopsy<E005> from start to finish.", "En clair, <E049><E003 6><E145 1 0><E118 1 0.5><E003 10><E025 2>le professeur Mikotoba a assisté à <E006>l'intégralité\r\nde l'autopsie<E005> du début à la fin.");
                R(ref s, "The defence demands that Professor Mikotoba be\r\nsummoned as a witness as a matter of urgency!", "La défense exige que le professeur Mikotoba soit cité\r\nà comparaître d'urgence comme témoin !");
                R(ref s, "Whatever really happened in that autopsy laboratory ten\r\nyears ago...<E003 10><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>is something only he can tell us!", "Ce qui s'est réellement produit dans cette salle d'autopsie il y\r\na dix ans...<E003 10><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>lui seul est désormais en mesure de nous le révéler !");
                R(ref s, "The defence's demand is denied.", "La demande de la défense est rejetée.");
                R(ref s, "What?", "Quoi ?");
                R(ref s, "But Professor Mikotoba is in London at this very moment!<E049><E003 14>\r\n<E025 1><E346>We could summon him to the stand in minutes!", "Mais le professeur Mikotoba est à Londres en ce moment même !<E049><E003 14>\r\n<E025 1><E346>Nous pourrions l'amener à la barre en quelques minutes !");
                R(ref s, "(No, <E003 10><E025 2>of course he's not going to agree to it.<E003 10> <E025 2>Stronghart has\r\nno intention of summoning anyone who knows.)", "(Non, <E003 10><E025 2>il ne l'acceptera jamais.<E003 10> <E025 2>Stronghart n'a aucune\r\nintention de convoquer quiconque connaît la vérité.)");
                R(ref s, "(He's too concerned about <E006>protecting himself<E007>!)", "(Il ne songe qu'à <E006>se protéger lui-même<E007> !)");
                R(ref s, "Prosecutor Asogi, <E049><E003 10><E025 2>let me refresh your memory, <E049><E003 6>as you\r\nseem to have forgotten the prosecution's stance:", "Procureur Asogi, <E049><E003 10><E025 2>laissez-moi vous rafraîchir la mémoire, <E049><E003 6>car\r\nvous semblez oublier la position de votre ministère :");
                R(ref s, "Only minutes ago, <E049><E003 8>you accused the defendant of being the\r\nReaper and of masterminding the assassin exchange.", "Il y a quelques instants à peine, <E049><E003 8>vous accusiez le prévenu d'être\r\nle Faucheur et d'avoir orchestré cet échange d'assassins.");
                R(ref s, "I, <E049><E003 8>I did, <E049><E003 8><E025 3>yes...", "C'est... <E049><E003 8>c'est exact, <E049><E003 8><E025 3>oui...");
                R(ref s, "So present your evidence for those claims <E049><E003 12><E025 1><E332>and make your\r\ncase complete!", "Produisez donc les preuves de ces allégations <E049><E003 12><E025 1><E332>et achevez\r\nvotre démonstration !");
                R(ref s, "I...<E003 14>I...", "Je...<E003 14>je...");
                R(ref s, "At this time, <E049><E003 8>I don't have the requisite evidence.<E049><E003 16><E145 112 6><E117 112 7>\r\n<E025 1><E345>But that's exactly why we need witness testimony!", "Pour l'heure, <E049><E003 8>je n'ai point la preuve requise.<E049><E003 16><E145 112 6><E117 112 7>\r\n<E025 1><E345>Mais c'est précisément pourquoi ce témoignage est vital !");
                R(ref s, "The Professor case is closed.<E049><E003 14> <E025 2>There are no clues in the\r\ndistant past that will bolster your argument today.", "L'affaire du Professeur est close.<E049><E003 14> <E025 2>Aucun vestige du passé ne\r\nviendra étayer votre plaidoirie aujourd'hui.");
                R(ref s, "I'm afraid to say, <E049><E003 12><E025 3>Prosecutor Asogi...", "J'ai bien peur, <E049><E003 12><E025 3>procureur Asogi...");
                R(ref s, "...that you would appear to be possessed by the spirit of\r\nyour late homicidal father.", "... que vous ne soyez possédé par les chimères de feu votre père,\r\nce criminel sanguinaire.");
                R(ref s, "Now, <E049><E003 8><E025 2>as I stated earlier, <E049><E003 8>this court has already reached a\r\nconclusion with respect to the matter at hand.", "À présent, <E049><E003 8><E025 2>comme je l'ai déjà rappelé, <E049><E003 8>cette cour est parvenue\r\nà une conclusion quant au litige présent.");
                R(ref s, "Inspector Gregson was murdered by Japanese Supreme\r\nCourt Judge Seishiro Jigoku.", "L'inspecteur Gregson a été assassiné par le juge de la Cour\r\nsuprême du Japon, Seishiro Jigoku.");
                R(ref s, "As for any hidden circumstances that may exist, <E049><E003 10>they will\r\nbe investigated in due course by the proper authorities.", "Quant aux circonstances sous-jacentes qui pourraient subsister,<E049><E003 10>\r\nelles seront examinées en temps voulu par les autorités compétentes.");
                R(ref s, "But we all know what will happen!", "Mais nous savons tous ce qui va se passer !");
                R(ref s, "That'll just give the mastermind of the whole venture\r\ntime <E049><E003 2><E025 1><E164 1 71 1 2 5 0 1 1><E118 1 1.3><E139 1>to cover his tracks again!", "Cela ne fera que donner à l'instigateur de tout ceci le temps<E049><E003 2><E025 1><E164 1 71 1 2 5 0 1 1><E118 1 1.3><E139 1>\r\nde faire disparaître ses traces à nouveau !");
                R(ref s, "By which you mean me?", "Par là, vous voulez dire... moi ?");
                R(ref s, "Your punishment for this contemptible behaviour will be\r\ndecided at a later date.<E049><E003 8> <E145 61 4><E118 61 0.5><E003 6><E025 3>As for you, <E049><E003 8><E025 2>Prosecutor Asogi...", "La sanction de cet outrage intolérable sera décidée ultérieurement.<E049><E003 8>\r\n<E145 61 4><E118 61 0.5><E003 6><E025 3>Quant à vous, <E049><E003 8><E025 2>procureur Asogi...");
                R(ref s, "...you will be remanded following these proceedings.<E049><E003 15><E145 61 7><E118 61 0.5>\r\n<E025 2>Willingly, <E049><E003 8><E025 3>I trust...<E003 12>since you gave your word.", "... vous serez placé sous les verrous à l'issue de cette séance.<E049><E003 15><E145 61 7><E118 61 0.5>\r\n<E025 2>De plein gré, <E049><E003 8><E025 3>j'ose l'espérer...<E003 12>puisque vous aviez engagé votre parole.");
                R(ref s, "Argh!", "Argh !");
                R(ref s, "This futile game of revenge is over...<E049><E003 15><E164 61 12 1 2 5 1 2 1><E139 61><E025 1>young Master Asogi.", "Cette vaine mascarade de vengeance touche à sa fin...<E049><E003 15><E164 61 12 1 2 5 1 2 1><E139 61><E025 1>jeune maître Asogi.");
                R(ref s, "Grrr...<E003 40>", "Grrr...<E003 40>");
                R(ref s, "UWAAAA<E338>AAAAAAAAAAAAAAAAAAAA<E356>AAAAAAAAA\r\nAAAAAAAAAAAAAAAAAA<E345>AAAAAAAAAAAAAAARGH!<E046><E003 45>", "UWAAAA<E338>AAAAAAAAAAAAAAAAAAAA<E356>AAAAAAAAA\r\nAAAAAAAAAAAAAAAAAA<E345>AAAAAAAAAAAAAAARGH !<E046><E003 45>");
                return s;
            };

            // [105] BB\script\output\_sce04_c304_0030_eng#6
            entryTranslators[@"BB\script\output\_sce04_c304_0030_eng#6"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'est évident <E049><E003 8><E025 2>que prolonger les débats serait totalement\r\nvain.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Lord Drake Van Peers, <E049><E003 8><E025 2>j'aime à penser que, si égaré\r\nfussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "... vous avez agi par devoir envers la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver à ce constat...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de cette cour, <E049><E003 6><E025 3>je déclare\r\nl'accusé, <E049><E003 6><E025 3>Lord Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "Ceci clôt les débats.<E049><E003 10>\r\n<E025 2>La séance est levée !");
                return s;
            };

            // [106] BB\script\output\_sce04_c304_0040_eng#2
            entryTranslators[@"BB\script\output\_sce04_c304_0040_eng#2"] = (s) => {
                R(ref s, "That will be all!<E049><E003 15> <E145 61 0><E118 61 0.7><E025 3>I hereby declare this trial to be over.<E049><E003 12>\r\n<E025 2>Court is–", "C'en est assez !<E049><E003 15> <E145 61 0><E118 61 0.7><E025 3>Je déclare ce procès clos.<E049><E003 12>\r\n<E025 2>L'audience est—");
                R(ref s, "M...<E003 16><E025 1><E145 1 2><E046>Mr Sholmes!", "M...<E003 16><E025 1><E145 1 2><E046>Monsieur Sholmes !");
                R(ref s, "This is no place for amateur detection, <E049><E003 8>Mr Sholmes.", "Cet endroit n'est pas fait pour les détectives amateurs, <E049><E003 8>monsieur Sholmes.");
                R(ref s, "May I remind you that these proceedings are closed to the\r\ngeneral public.<E049><E003 14> <E025 1><E346>You will leave the courtroom at once!", "Dois-je vous rappeler que cette séance se tient à huis clos ?<E049><E003 14>\r\n<E025 1><E346>Quittez la salle immédiatement !");
                R(ref s, "Mr Sholmes was instrumental in the apprehension of\r\nSeishiro Jigoku before he fled from Europe.", "M. Sholmes a joué un rôle déterminant dans l'arrestation de\r\nSeishiro Jigoku avant qu'il ne fuie l'Europe.");
                R(ref s, "The court should hear what he has to say!", "La cour se doit d'entendre ce qu'il a à dire !");
                R(ref s, "Lord Mael Stronghart...", "Lord Mael Stronghart...");
                R(ref s, "...it's imperative that you refrain from bringing this trial to\r\nan end at this stage.", "... il est impératif que vous renonciez à clore ce procès en l'état.");
                R(ref s, "Is it really?<E049><E003 12>\r\n<E025 3>And why would that be?", "Vraiment ?<E049><E003 12>\r\n<E025 3>Et pour quelle raison, je vous prie ?");
                R(ref s, "You need only recall your own words from the opening\r\nof the trial to answer that question.<E049><E003 10> <E025 3>If I may...", "Il vous suffit de vous remémorer vos propres paroles prononcées\r\nà l'ouverture des débats pour répondre.<E049><E003 10> <E025 3>Si vous me permettez...");
                R(ref s, "‘We will <E006>stop at nothing<E005> to uncover the whole truth\r\nbehind these disturbing findings!’", "« Nous ne <E006>reculerons devant rien<E005> pour faire toute la lumière\r\nsur ces troublantes découvertes ! »");
                R(ref s, "Surely it can't be...", "Ne me dites tout de même pas...");
                R(ref s, "...that the shock of being accused of being the Reaper\r\nyourself has erased that from your memory...<E003 10><E025 3>can it?", "... que le choc d'être vous-même désigné comme le Faucheur\r\na effacé cette promesse de votre mémoire...<E003 10><E025 3>n'est-ce pas ?");
                R(ref s, "The whole truth, <E049><E003 6>sir, <E049><E003 10><E345><E342><E025 1>has already been uncovered!", "Toute la vérité, <E049><E003 6>monsieur, <E049><E003 10><E345><E342><E025 1>a déjà été établie !");
                R(ref s, "It would seem that we have a great many important\r\nmembers of the judiciary present here today.", "Il semble que nous ayons ici rassemblés quantité de membres\r\néminents de l'institution judiciaire.");
                R(ref s, "I put it to you, <E049><E003 6>my dear fellows...<E049><E003 10><E025 2>should the trial end at\r\nthis juncture?", "Je vous le demande, <E049><E003 6>mes chers confrères...<E049><E003 10><E025 2>le procès doit-il\r\nprendre fin en cet instant ?");
                R(ref s, "After all, <E049><E003 8>why have you been invited to attend?<E049><E003 12><E164 2 80 1 2 7 0 0 1><E139 2>\r\n<E025 2>To nod along to the prevarications of your superiors?", "Après tout, <E049><E003 8>pourquoi êtes-vous conviés ?<E049><E003 12><E164 2 80 1 2 7 0 0 1><E139 2>\r\n<E025 2>Pour acquiescer docilement aux faux-fuyants de vos supérieurs ?");
                R(ref s, "Order!<E049><E003 12> <E025 1><E342>Order in court!", "Silence !<E049><E003 12> <E025 1><E342>Silence dans ce tribunal !");
                R(ref s, "It seems to me that we stand before a door that leads to a\r\nnew era of legal practices.<E049><E003 10> A door that is ajar.", "Il me semble que nous nous tenons devant la porte d'une ère\r\nnouvelle de la pratique du droit.<E049><E003 10> Une porte entrouverte.");
                R(ref s, "Let us emerge from the shadows of the Reaper's\r\ndecade-long ascendancy.", "Sortons enfin de l'ombre où nous plonge le règne décennal\r\ndu Faucheur.");
                R(ref s, "For you and you alone, <E049><E003 8><E025 2>my dear fellows, <E049><E003 8><E462 0.614773 99.496185 70.956818 9 1><E464 0.614834 99.496185 259.304260 9 1><E485 97 9 1><E163 2 79 1 2 8 0 1 1><E139 2><E094 1 21 6><E025 1>have the power\r\nto push this door open now!<E093 1 22 4>", "Car vous et vous seuls, <E049><E003 8><E025 2>chers collègues, <E049><E003 8><E462 0.614773 99.496185 70.956818 9 1><E464 0.614834 99.496185 259.304260 9 1><E485 97 9 1><E163 2 79 1 2 8 0 1 1><E139 2><E094 1 21 6><E025 1>avez le pouvoir\r\nde pousser cette porte dès aujourd'hui !<E093 1 22 4>");
                R(ref s, "The auditors in the gallery have no rights to express an\r\nopinion on court proceedings!<E049><E003 8> <E164 61 12 1 2 5 0 2 1><E118 61 1.3><E139 61><E025 1>Silence!", "Le public des tribunes n'a aucun droit d'exprimer son avis sur la\r\nprocédure !<E049><E003 8> <E164 61 12 1 2 5 0 2 1><E118 61 1.3><E139 61><E025 1>Silence !");
                R(ref s, "He's right.<E003 12>\r\n<E042><CNTR><E025 2>The judge has absolute authority here.", "Il a raison.<E003 12>\r\n<E042><CNTR><E025 2>Le juge détient l'autorité absolue céans.");
                R(ref s, "Yes, <E003 8><E025 2>if he calls the trial to an end, <E003 12><E025 1>it must end!", "Oui, <E003 8><E025 2>s'il décide de lever la séance, <E003 12><E025 1>elle doit prendre fin !");
                R(ref s, "But will that really do?", "Mais pouvons-nous vraiment nous en satisfaire ?");
                R(ref s, "I sense dark things occurring behind the scenes...<E003 10>\r\n<E042><CNTR><E025 3>Dark things indeed...", "Je pressens de sombres manigances dans les coulisses...<E003 10>\r\n<E042><CNTR><E025 3>De bien sombres affaires en vérité...");
                R(ref s, "Is there a single person here present who\r\n<E042><CNTR>can honestly say he doesn't sense the same?", "Y a-t-il une seule personne ici présente qui puisse\r\n<E042><CNTR>affirmer loyalement ne pas ressentir la même chose ?");
                R(ref s, "What...<E049><E003 12> What's...?", "Que...<E049><E003 12> Qu'est-ce que... ?");
                R(ref s, "The trial should go on!<E003 15>\r\n<E042><CNTR><E342><E338>Summon the witness!", "Le procès doit continuer !<E003 15>\r\n<E042><CNTR><E342><E338>Appelez le témoin à la barre !");
                R(ref s, "That's right!<E003 14> <E025 1><E046><E339>We need to clear this up before that\r\n<E042><CNTR>young Japanese fellow is remanded in custody!", "C'est exact !<E003 14> <E025 1><E046><E339>Il faut éclaircir ceci avant que ce\r\n<E042><CNTR>jeune Japonais ne soit jeté en prison !");
                R(ref s, "My Lord!<E003 15> <E338><E342><E025 2>You assured those present that\r\n<E042><CNTR>you would uncover the whole truth here!", "Votre Grâce !<E003 15> <E338><E342><E025 2>Vous nous aviez assuré que\r\n<E042><CNTR>vous feriez éclater toute la vérité !");
                R(ref s, "Vindicate yourself of this outlandish accusation!", "Dédouanez-vous donc de cette folle accusation !");
                R(ref s, "The truth, <E003 8>the whole truth <E003 6>and nothing but the truth!<E003 15>\r\n<E042><CNTR><E025 1><E332>That's the very foundation of British law!", "La vérité, <E003 8>toute la vérité, <E003 6>et rien que la vérité !<E003 15>\r\n<E042><CNTR><E025 1><E332>Tel est le fondement même du droit britannique !");
                R(ref s, "A toast...<E003 12><E025 2>to my dependable colleagues in the gallery!", "Je lève mon verre...<E003 12><E025 2>à mes dévoués confrères des tribunes !");
                return s;
            };

            // [107] BB\script\output\_sce04_c304_0050_eng#2
            entryTranslators[@"BB\script\output\_sce04_c304_0050_eng#2"] = (s) => {
                R(ref s, "On with the trial!<E003 10>\r\n<E042><CNTR><E025 2><E338><E341>On with the trial!", "Que le procès continue !<E003 10>\r\n<E042><CNTR><E025 2><E338><E341>Que le procès continue !");
                R(ref s, "Testify!<E003 20> Testify!<E003 20> <E341>Testify!", "Témoignez !<E003 20> Témoignez !<E003 20> <E341>Témoignez !");
                R(ref s, "Well, <E049><E003 10>My Lord?", "Alors, <E049><E003 10>Votre Grâce ?");
                R(ref s, "You hear the voice of British justice, <E049><E003 8><E025 3>I take it?", "Vous entendez la voix de la justice britannique, <E049><E003 8><E025 3>j'imagine ?");
                R(ref s, "I think you'll find it will be rather awkward to silence.", "Vous conviendrez qu'il sera bien difficile de la réduire au silence.");
                R(ref s, "The court will recess briefly.", "La séance est suspendue pour une courte pause.");
                R(ref s, "I have no intention of shrinking from these allegations.", "Je n'ai nullement l'intention de fuir face à de telles allégations.");
                R(ref s, "Bailiff!<E049><E003 15> <E025 1>Arrange for the subpoena of the witness at once!", "Huissier !<E049><E003 15> <E025 1>Délivrez immédiatement une citation à comparaître !");
                R(ref s, "As soon as the gentleman arrives at the courthouse,<E049><E003 8> <E025 2><E341>we\r\nshall reconvene.", "Dès que ce monsieur se présentera au palais,<E049><E003 8> <E025 2><E341>nous\r\nreprendrons les débats.");
                R(ref s, "A recess won't be necessary, <E049><E003 6>My Lord.", "Une suspension de séance ne sera point nécessaire, <E049><E003 6>Votre Grâce.");
                R(ref s, "Pardon?", "Plaît-il ?");
                R(ref s, "Mikotoba is a close friend of mine.<E049><E003 7> <E145 2 67><E118 2 1.1><E003 15><E330><E025 2>He accompanied me\r\ntoday and is waiting in the antechamber as we speak.", "Mikotoba est un de mes proches amis.<E049><E003 7> <E145 2 67><E118 2 1.1><E003 15><E330><E025 2>Il m'accompagnait\r\naujourd'hui et patiente dans l'antichambre à l'heure qu'il est.");
                R(ref s, "I do believe he's been enjoying a little trip down memory\r\nlane, <E049><E003 6>in fact.", "Je crois d'ailleurs qu'il se remémorait quelques souvenirs de jeunesse.");
                R(ref s, "What?!<E049><E003 10>\r\n<E025 1><E145 112 7><E149 112 4 4><E118 112 0.9><E003 8><E341>Professor Mikotoba is here in the courthouse?!", "Quoi ?!<E049><E003 10>\r\n<E025 1><E145 112 7><E149 112 4 4><E118 112 0.9><E003 8><E341>Le professeur Mikotoba est ici, au palais de justice ?!");
                R(ref s, "Mr Sholmes, <E049><E003 8>you...", "Monsieur Sholmes, <E049><E003 8>vous...");
                R(ref s, "You didn't know this would happen, <E049><E003 8><E341>did you?!", "Vous ne saviez tout de même pas que cela arriverait, <E049><E003 8><E341>si ?!");
                R(ref s, "My dear fellow, <E049><E003 8><E025 2><E163 2 79 1 2 8 0 1 1><E139 2>no one is in a better position to answer\r\nthat question than you, <E049><E003 6>surely.", "Mon cher ami, <E049><E003 8><E025 2><E163 2 79 1 2 8 0 1 1><E139 2>nul n'est mieux placé pour répondre à cette\r\nquestion que vous, <E049><E003 6>assurément.");
                R(ref s, "(I wasn't just asking for the fun of it, <E003 6>you know.)", "(Je ne posais pas la question pour le plaisir, <E003 6>vous savez.)");
                R(ref s, "Well, <E049><E003 8>I must thank you for your assistance in this matter...<E049><E003 14>\r\nMr Sholmes.", "Bien, <E049><E003 8>je me dois de vous remercier de votre concours...<E049><E003 14>\r\nmonsieur Sholmes.");
                R(ref s, "...you are of no further use here.<E049><E003 12>\r\n<E025 2><E239>Kindly leave the courtroom at once.", "... vous n'êtes plus d'aucune utilité ici.<E049><E003 12>\r\n<E025 2><E239>Ayez l'obligeance de quitter la salle immédiatement.");
                R(ref s, "But of course.<E049><E003 12> <E025 2>In truth, <E049><E003 8>I find myself rather busy now as a\r\nresult of these developments.", "Mais bien sûr.<E049><E003 12> <E025 2>En vérité, <E049><E003 8>je me trouve fort occupé à présent à\r\nla suite de ces développements.");
                R(ref s, "Mr Naruhodo!", "Monsieur Naruhodo !");
                R(ref s, "Ah!<E049><E003 15> <E025 1><E145 1 65><E342><E331>...Yes?", "Ah !<E049><E003 15> <E025 1><E145 1 65><E342><E331>... Oui ?");
                R(ref s, "I trust you have Iris's little <E006>lucky charm<E005> with you?", "J'espère que vous avez sur vous le petit <E006>porte-bonheur<E005> d'Iris ?");
                R(ref s, "Absolutely!<E049><E003 20> <E060 0 151 1 0><E025 1><E335><E342>It's still in my pocket.", "Absolument !<E049><E003 20> <E060 0 151 1 0><E025 1><E335><E342>Il est toujours dans ma poche.");
                R(ref s, "She sends her regards, <E049><E003 8>and a reminder:", "Elle vous transmet ses amitiés, <E049><E003 8>avec ce rappel :");
                R(ref s, "If you find yourself at a dead end, <E049><E003 8>the ears are at your\r\ndisposal.<E049><E003 10> <E164 2 81 1 2 6 0 1 1><E173 2 29 15 2><E139 2><E025 2>...Just one tug, <E049><E003 6>if you please.", "Si vous vous trouvez dans une impasse, <E049><E003 8>les oreilles sont à votre\r\ndisposition.<E049><E003 10> <E164 2 81 1 2 6 0 1 1><E173 2 29 15 2><E139 2><E025 2>... Tirez simplement dessus, <E049><E003 6>s'il vous plaît.");
                R(ref s, "Oh, <E049><E003 8>um...<E049><E003 14><E025 1><E145 1 65><E331><E342>of course!", "Oh, <E049><E003 8>euh...<E049><E003 14><E025 1><E145 1 65><E331><E342>bien sûr !");
                R(ref s, "In that case, <E049><E003 12><E145 61 7><E118 61 0.55>the trial will continue without delay.", "En ce cas, <E049><E003 12><E145 61 7><E118 61 0.55>le procès se poursuivra sans délai.");
                R(ref s, "Bailiff!<E049><E003 12> <E346><E025 1>Show the witness to the stand!", "Huissier !<E049><E003 12> <E346><E025 1>Conduisez le témoin à la barre !");
                R(ref s, "(So it's Lord Stronghart...<E003 12>\r\n<E025 2>He's the Reaper of the Bailey.)", "(C'est donc Lord Stronghart...<E003 12>\r\n<E025 2>C'est lui, le Faucheur du tribunal.)");
                R(ref s, "(Where exactly is this trial going to take me, I wonder?)", "(Jusqu'où ce procès va-t-il m'entraîner ?)");
                R(ref s, "(Just how deep am I about to be plunged into the\r\nblackness of the abyss?)", "(À quelle profondeur vais-je être plongé dans les ténèbres\r\nde cet abîme ?)");
                R(ref s, "(Well...<E003 12>I'm ready.)", "(Eh bien...<E003 12>je suis prêt.)");
                R(ref s, "(I'm ready to head into the heart of this maelstrom<E003 12> <E025 1><E342>and\r\nconfront whatever horrors it tries to drown me under!)", "(Je suis prêt à affronter le cœur de ce maelström<E003 12> <E025 1><E342>et à défier\r\ntoutes les horreurs qu'il tentera de déverser sur moi !)");
                return s;
            };

        }
    }
}
